// spec: specs/ssr-infra.md (1.2–1.3) · кейсы: .qa/tests/ssr-infra/SSR-INFRA-02.md, SSR-INFRA-03.md
// seed: tests/seed.spec.ts (гость) · прод: только GET через API request, без браузера и JS.
import { test, expect } from '@playwright/test';
import { PRIVATE_PATHS, SERVICE_PATHS, robotsMeta } from './ssr-infra.helpers';

test.describe('SSR/SSG — сырой HTML', () => {
  test('Приватные страницы: #root пустой, noindex в meta и/или X-Robots-Tag #be4863 @desktop @prod-safe', async ({ request }) => {
    for (const path of PRIVATE_PATHS) {
      await test.step(path, async () => {
        const res = await request.get(path);
        expect(res.status(), `${path}: статус`).toBe(200);
        const html = await res.text();
        expect(html, `${path}: #root пустой`).toMatch(/<div\s+id=["']root["']\s*><\/div>/i);
        expect(html, `${path}: нет SEO-блока`).not.toContain('data-seo-body');

        const header = res.headers()['x-robots-tag'] ?? '';
        const meta = robotsMeta(html);
        const noindex = /noindex/i.test(header) || meta.some((m) => /noindex/i.test(m));
        expect(noindex, `${path}: noindex (X-Robots-Tag «${header}», meta ${JSON.stringify(meta)})`).toBe(true);
        expect(meta.some((m) => /(^|,\s*)index\b/i.test(m)), `${path}: нет meta «index»`).toBe(false);
      });
    }
  });

  test('/admin и /auth: X-Robots-Tag noindex, #root пустой #be4863 @desktop @prod-safe', async ({ request }) => {
    for (const path of SERVICE_PATHS) {
      await test.step(path, async () => {
        const res = await request.get(path);
        expect(res.status(), `${path}: статус`).toBe(200);
        expect(res.headers()['x-robots-tag'] ?? '', `${path}: X-Robots-Tag`).toMatch(/noindex/i);
        const html = await res.text();
        expect(html, `${path}: #root пустой`).toMatch(/<div\s+id=["']root["']\s*><\/div>/i);
      });
    }
  });
});
